const fourTwentyFiveMatches = (ev14.match(/4–25×/g) || []).length;
assert(fourTwentyFiveMatches === 1,
  'EXP-618 ISS-2726: WIN-014.detail_evidence contains "4\u201325\xd7" exactly once (got ' + fourTwentyFiveMatches + ')');

